import argparse,datetime,hashlib,json,math,sys
sys.dont_write_bytecode=True
import numpy as np
import pandas as pd
FILES=['state_age_year_observed.csv','national_family_shares.csv','matched_geography_drug_rows.csv.gz','glimepiride_state_models.csv','excluded_geographic_units.csv']
def sha(p):
 with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def agg(g):
 known=g.GE65_Tot_30day_Fills.notna();v=g[known];m=v.Gnrc_Name.str.contains('glimepiride',case=False)
 so=v.GE65_Tot_30day_Fills.sum();sy=(v.Tot_30day_Fills-v.GE65_Tot_30day_Fills).sum();go=v.loc[m,'GE65_Tot_30day_Fills'].sum();gy=(v.loc[m,'Tot_30day_Fills']-v.loc[m,'GE65_Tot_30day_Fills']).sum()
 return dict(old_su=so,young_su=sy,old_glime=go,young_glime=gy,old_share=100*go/so,young_share=100*gy/sy,gap=100*(go/so-gy/sy),suppressed_rows=int((~known).sum()),suppressed_all_age_su=g.loc[~known,'Tot_30day_Fills'].sum(),all_age_su=g.Tot_30day_Fills.sum(),all_age_glime=g.loc[g.Gnrc_Name.str.contains('glimepiride',case=False),'Tot_30day_Fills'].sum())
def main():
 default=Path(__file__).resolve().parents[1];ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--input-dir',type=Path,default=default.parent/'S2_LASU_glimepiride_addendum_v1_6');ap.add_argument('--output-dir',type=Path,default=default);a=ap.parse_args();assert a.input_dir.resolve()!=a.output_dir.resolve()
 T=a.output_dir/'tables';A=a.output_dir/'audit';T.mkdir(parents=True,exist_ok=True);A.mkdir(parents=True,exist_ok=True)
 inputs={f:sha(a.input_dir/'tables'/f) for f in FILES}
 p=pd.read_csv(a.input_dir/'tables'/FILES[0]);n=pd.read_csv(a.input_dir/'tables'/FILES[1]);raw=pd.read_csv(a.input_dir/'tables'/FILES[2],dtype={'Prscrbr_Geo_Cd':str});models=pd.read_csv(a.input_dir/'tables'/FILES[3]);excluded=pd.read_csv(a.input_dir/'tables'/FILES[4],dtype={'code':str})
 assert len(p)==1200 and set(p.year)==set(range(2013,2025)) and not p.duplicated(['state','year','age']).any();assert set(raw.Prscrbr_Geo_Lvl)=={'National','State'}
 names=set(p.state_name);assert len(names)==50
 rows=[];cs=[];coverage=[];drug=[];errors=[];pairs=[]
 for year,gy in p.groupby('year',sort=True):
  old=gy[gy.age.eq('ge65')].set_index('state').sort_index();young=gy[gy.age.eq('lt65')].set_index('state').sort_index();assert old.index.equals(young.index) and len(old)==50
  vo=old.su_observed.to_numpy();vy=young.su_observed.to_numpy();po=100*old.glimepiride_volume.to_numpy()/vo;py=100*young.glimepiride_volume.to_numpy()/vy
  ao=vo/vo.sum();ay=vy/vy.sum();h=vo*vy/(vo+vy);q=h/h.sum();gap=po-py;pooled_o=float(ao@po);pooled_y=float(ay@py);d50=pooled_o-pooled_y;within=float(q@gap);co=float((ao-q)@po);cy=float(-(ay-q)@py);comp=co+cy
  kw=float(((ao+ay)/2)@gap);kc=float((ao-ay)@((po+py)/2));yso=float(ay@po);yw=float(ay@gap);yc=float((ao-ay)@po)
  independent=math.fsum(float(h[i]*(po[i]-py[i])) for i in range(50))/math.fsum(h)
  errors.extend([abs(d50-within-comp),abs(d50-kw-kc),abs(d50-yw-yc),abs(within-independent)])
  rn=raw[raw.year.eq(year)&raw.Prscrbr_Geo_Lvl.eq('National')];rs=raw[raw.year.eq(year)&raw.Prscrbr_Geo_Lvl.eq('State')];r50=rs[rs.Prscrbr_Geo_Desc.isin(names)];rnon=rs[~rs.Prscrbr_Geo_Desc.isin(names)]
  an=agg(rn);aa=agg(rs);a50=agg(r50);anon=agg(rnon);pub=n[n.year.eq(year)].set_index('age');dn=float(pub.loc['ge65','glimepiride_share_pct']-pub.loc['lt65','glimepiride_share_pct']);errors.extend([abs(d50-a50['gap']),abs(dn-an['gap'])]);en=aa['gap']-d50;resid=dn-aa['gap'];ratio=h/vy
  errors.append(abs(dn-(within+comp+en+resid)))
  expected_missing=an['all_age_su']-aa['all_age_su']+aa['suppressed_all_age_su']-an['suppressed_all_age_su'];observed_missing=an['old_su']+an['young_su']-aa['old_su']-aa['young_su'];assert abs(expected_missing-observed_missing)<1e-6
  rows.append(dict(year=int(year),national_published_gap_pp=dn,state50_pooled_gap_pp=d50,state50_within_harmonic_gap_pp=within,state50_geographic_weight_component_pp=comp,component_old_weight_pp=co,component_young_weight_pp=cy,observed_non50_addition_pp=en,publication_suppression_residual_pp=resid,national_minus_state50_pp=dn-d50,all_published_subnational_visible_gap_pp=aa['gap'],state50_ge65_share_own_weights_pct=pooled_o,state50_ge65_share_young_weights_pct=yso,state50_lt65_share_own_weights_pct=pooled_y,young_weighted_within_pp=yw,young_standardization_composition_pp=yc,kitagawa_within_pp=kw,kitagawa_composition_pp=kc,harmonic_weight_sum=h.sum(),harmonic_over_young_volume_min=ratio.min(),harmonic_over_young_volume_median=np.median(ratio),harmonic_over_young_volume_max=ratio.max(),harmonic_vs_young_normalized_total_variation=.5*np.abs(q-ay).sum(),national_minus_subnational_published_all_age_su=an['all_age_su']-aa['all_age_su'],published_subnational_suppressed_all_age_su=aa['suppressed_all_age_su'],national_suppressed_all_age_su=an['suppressed_all_age_su'],national_suppressed_rows=an['suppressed_rows'],national_minus_subnational_visible_all_age_su=an['old_su']+an['young_su']-aa['old_su']-aa['young_su']))
  for i,state in enumerate(old.index):
   cs.append(dict(year=int(year),state=state,old_su_volume=vo[i],young_su_volume=vy[i],old_glime_share_pct=po[i],young_glime_share_pct=py[i],gap_pp=gap[i],age_specific_old_state_weight=ao[i],age_specific_young_state_weight=ay[i],harmonic_pair_weight=h[i],normalized_harmonic_weight=q[i],harmonic_over_young_volume=ratio[i],within_component_pp=q[i]*gap[i],composition_component_pp=(ao[i]-q[i])*po[i]-(ay[i]-q[i])*py[i]));pairs.append((h[i],gap[i]))
  for label,ag in [('National',an),('50_states',a50),('non50_published_units',anon),('all_subnational_units',aa)]:coverage.append(dict(year=int(year),universe=label,**ag))
  keys=['Gnrc_Name','Brnd_Name'];nr=rn.groupby(keys).Tot_30day_Fills.sum().rename('national');sr=rs.groupby(keys).Tot_30day_Fills.sum().rename('subnational');cmp=pd.concat([nr,sr],axis=1)
  for key,rr in cmp.iterrows():drug.append(dict(year=int(year),Gnrc_Name=key[0],Brnd_Name=key[1],national_all_age_volume=rr.national,published_subnational_all_age_volume=rr.subnational,all_age_national_minus_subnational=rr.national-rr.subnational,reporting_status='BOTH_PRESENT' if rr.notna().all() else 'UNMATCHED_PRODUCT_UNIVERSE'))
 annual=pd.DataFrame(rows);cc=pd.DataFrame(cs);cov=pd.DataFrame(coverage);pooled=math.fsum(w*g for w,g in pairs)/math.fsum(w for w,g in pairs);pa=float(np.average(annual.state50_within_harmonic_gap_pp,weights=annual.harmonic_weight_sum));primary=models[models.scenario.eq('observed')&models.period.eq('overall')].iloc[0];errors.extend([abs(pooled-float(primary.estimate_pp)),abs(pooled-pa)])
 assert max(errors)<1e-9,max(errors);assert all(sha(a.input_dir/'tables'/f)==v for f,v in inputs.items())
 for df,name in [(annual,'annual_geographic_decomposition.csv'),(cc,'state_year_weights_and_components.csv'),(cov,'publication_universe_coverage.csv'),(pd.DataFrame(drug),'national_subnational_drug_volume_audit.csv'),(excluded[excluded.level.ne('National')],'excluded_geographic_units.csv')]:df.to_csv(T/name,index=False,float_format='%.17g')
 qa=dict(status='PASS',finished_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),years=12,state_years=600,exact_identity_tolerance_pp=1e-9,max_validation_error=max(errors),inputs_unchanged=True,input_sha256=inputs,pooled_from_state_years_pp=pooled,pooled_from_annual_pp=pa,pooled_v16_model_pp=float(primary.estimate_pp),composition_negative_all12=bool(annual.state50_geographic_weight_component_pp.lt(0).all()),annual_within_exceeds_national_all12=bool((annual.state50_within_harmonic_gap_pp>annual.national_published_gap_pp).all()),inference='Exact arithmetic only; no new model,CI,p-value or causal attribution',national_bridge='national=harmonic within+geographic weight component+observed non50 addition+publication/suppression residual');(A/'QA.json').write_text(json.dumps(qa,indent=2)+'\n')
 selected=annual[annual.year.isin([2013,2019,2024])];report=['# v1.7 geography decomposition','','Status: PASS. Post hoc exact arithmetic audit; old analyses are unchanged.','','All shares refer to glimepiride-family 30-day fills / all sulfonylurea 30-day fills. Geographic weights describe dispensing volumes, not beneficiary counts or residence distributions.','','|Year|National gap|50-state pooled gap|Annual paired-weight within-state gap|Geographic weight component|Adding visible non50 units|Publication/suppression residual|','|---|---:|---:|---:|---:|---:|---:|']
 for r in selected.itertuples():report.append(f'|{r.year}|{r.national_published_gap_pp:.6f}|{r.state50_pooled_gap_pp:.6f}|{r.state50_within_harmonic_gap_pp:.6f}|{r.state50_geographic_weight_component_pp:.6f}|{r.observed_non50_addition_pp:.6f}|{r.publication_suppression_residual_pp:.6f}|')
 report+=['','All differences are percentage points. The last four columns sum exactly to the national difference. Within-state plus geographic weight columns sum exactly to the 50-state pooled difference.','','For each year, p_o and p_y are state shares; a_o and a_y are age-specific normalized state SU volumes; q is proportional to V_o V_y/(V_o+V_y). W=sum[q(p_o-p_y)] and C=sum[(a_o-q)p_o]−sum[(a_y-q)p_y]. Thus D50=W+C. CSV also supplies symmetric Kitagawa and younger-volume standardizations; no decomposition is uniquely causal.','',f'Pooled 2013–2024 estimate: {pooled:.12f} pp, matching v1.6. It is the annual within-state differences averaged using annual sums of unnormalized paired weights, not the 2024 within-state or national value.','','Geographic weight component is negative in all 12 years. Reweighting older-group state shares by younger-group SU-volume weights increases the older-group mean. This supports a volume-composition explanation for the smaller pooled age difference; it does not establish beneficiary residence or causal selection.','','National-minus-50-state difference is not assigned wholly to excluded units. The exact bridge separates (i) adding visible published rows for DC, territories, overseas and unknown units and (ii) remaining national-versus-visible-subnational residual. The latter includes age-suppressed published rows at both national and subnational levels and national/subnational publication-universe or rounding discrepancies. Entire omitted geography-product cells cannot be allocated to ages from these public tables.','','The final volume column equals column 2 plus column 3 minus column 4; national suppressed age rows are omitted from both age groups just as in v1.6.','','|Year|National minus published subnational all-age SU|All-age SU in age-suppressed subnational rows|All-age SU in age-suppressed national rows|National minus visible subnational SU|','|---|---:|---:|---:|---:|']
 for r in selected.itertuples():report.append(f'|{r.year}|{r.national_minus_subnational_published_all_age_su:.2f}|{r.published_subnational_suppressed_all_age_su:.2f}|{r.national_suppressed_all_age_su:.2f}|{r.national_minus_subnational_visible_all_age_su:.2f}|')
 report+=['',f'Across 600 state-years, harmonic/young-volume ratio range {cc.harmonic_over_young_volume.min():.4f}–{cc.harmonic_over_young_volume.max():.4f}, median {cc.harmonic_over_young_volume.median():.4f}. Annual total-variation distance between normalized harmonic and young-volume weights range {annual.harmonic_vs_young_normalized_total_variation.min():.4f}–{annual.harmonic_vs_young_normalized_total_variation.max():.4f}. Paired weight favors the smaller-volume age group but is not identical to young-group volume. Methods should give the exact formula instead of an unnecessary approximation.','','Recommended Results: In 2024, the annual within-state difference was 3.91 percentage points, versus 2.56 nationally; age-specific geographic distributions of sulfonylurea dispensing volumes partly explained the difference. The 4.04-point estimate pools all 12 years.','','Reproduce: python code/decompose.py --input-dir ../S2_LASU_glimepiride_addendum_v1_6 --output-dir /new/isolated/directory. Five CSV inputs are hashed before and after. No network access required.']
